def get(key):
    if key not in ENTRIES: raise ValueError(f"unknown key: {key}")
    return ENTRIES[key]

def png4(path, expected):
    with Image.open(path) as im:
        if im.mode != "P": raise ValueError(f"{path}: indexed PNG required")
        w,h=im.size; px=list(im.getdata())
    if w%8 or h%8 or (px and max(px)>15): raise ValueError(f"{path}: invalid 4bpp PNG")
    out=bytearray()
    for ty in range(0,h,8):
      for tx in range(0,w,8):
       for y in range(8):
        row=(ty+y)*w+tx
        for x in range(0,8,2): out.append(px[row+x] | (px[row+x+1]<<4))
    if len(out)<expected or any(out[expected:]): raise ValueError(f"{path}: tile data/padding mismatch")
    return bytes(out[:expected])

def incraw(path):
    out=bytearray()
    for n,src in enumerate(Path(path).read_text(encoding="utf-8").splitlines(),1):
        line=src.split("@",1)[0].strip()
        if not line: continue
        m=re.fullmatch(r"\.(byte|2byte|4byte)\s+(.+)", line)
        if not m: raise ValueError(f"{path}:{n}: unsupported directive")
        width={"byte":1,"2byte":2,"4byte":4}[m.group(1)]
        for tok in m.group(2).split(","): out.extend(int(tok.strip(),0).to_bytes(width,"little"))
    return bytes(out)

def repack(key, raw, out):
    e=get(key)
    if len(raw)!=e["raw_size"]: raise ValueError(f"{key}: raw size mismatch")
    enc=repack_raw_with_plan(raw,e["plan"])
    if len(enc)!=e["stored_size"]: raise ValueError(f"{key}: stored size mismatch")
    Path(out).parent.mkdir(parents=True,exist_ok=True); Path(out).write_bytes(enc)

def palette(inp,out):
    with Image.open(inp) as im:
        if im.mode!="P": raise ValueError(f"{inp}: indexed PNG required")
        p=im.getpalette()
    raw=bytearray()
    for i in range(16):
        r,g,b=p[i*3:i*3+3]; v=(r>>3)|((g>>3)<<5)|((b>>3)<<10); raw.extend(v.to_bytes(2,"little"))
    Path(out).parent.mkdir(parents=True,exist_ok=True); Path(out).write_bytes(raw)

def main():
    ap=argparse.ArgumentParser(); sp=ap.add_subparsers(dest="cmd",required=True)
    p=sp.add_parser("repack-png"); p.add_argument("--key",required=True); p.add_argument("input"); p.add_argument("output")
    p=sp.add_parser("repack-inc"); p.add_argument("--key",required=True); p.add_argument("input"); p.add_argument("output")
    p=sp.add_parser("encode-palette"); p.add_argument("input"); p.add_argument("output")
    a=ap.parse_args()
    try:
        if a.cmd=="repack-png": e=get(a.key); repack(a.key,png4(Path(a.input),e["raw_size"]),a.output)
        elif a.cmd=="repack-inc": repack(a.key,incraw(a.input),a.output)
        else: palette(a.input,a.output)
    except (OSError,ValueError) as exc:
        print(f"ERROR: {exc}",file=sys.stderr); return 1
    return 0
if __name__=="__main__": raise SystemExit(main())
